function cheapestRoute(stops, roads, start, target) {
    const best = new Array(stops).fill(Infinity);
    best[start] = 0;
    for (let round = 1; round < stops; round++) {
        let changed = false;
        for (const [a, b, toll] of roads) {
            if (best[a] + toll < best[b]) {
                best[b] = best[a] + toll;
                changed = true;
            }
            if (best[b] + toll < best[a]) {
                best[a] = best[b] + toll;
                changed = true;
            }
        }
        if (!changed)
            break;
    }
    return best[target] === Infinity ? -1 : best[target];
}

function cheapestRoute(stops, roads, start, target) {
    const adjacent = Array.from({ length: stops }, () => []);
    for (const [a, b, toll] of roads) {
        adjacent[a].push([b, toll]);
        adjacent[b].push([a, toll]);
    }
    const heap = [];
    const push = (entry) => {
        heap.push(entry);
        let i = heap.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (heap[parent][0] <= heap[i][0])
                break;
            [heap[parent], heap[i]] = [heap[i], heap[parent]];
            i = parent;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                const left = 2 * i + 1;
                const right = left + 1;
                let smallest = i;
                if (left < heap.length && heap[left][0] < heap[smallest][0])
                    smallest = left;
                if (right < heap.length && heap[right][0] < heap[smallest][0])
                    smallest = right;
                if (smallest === i)
                    break;
                [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
                i = smallest;
            }
        }
        return top;
    };
    const best = new Array(stops).fill(Infinity);
    best[start] = 0;
    push([0, start]);
    while (heap.length > 0) {
        const [toll, stop] = pop();
        if (toll > best[stop])
            continue;
        if (stop === target)
            return toll;
        for (const [next, extra] of adjacent[stop]) {
            if (toll + extra < best[next]) {
                best[next] = toll + extra;
                push([toll + extra, next]);
            }
        }
    }
    return -1;
}
